begin;
create function pg_temp.afirma(ok boolean,msg text) returns void language plpgsql as $fn$
begin if ok is distinct from true then raise exception 'FALHOU: %',msg; end if; raise notice 'ok: %',msg; end $fn$;
insert into public.lojas(id,nome,slug) values ('ed000000-0000-0000-0000-000000000001','Nano eventos','nano-eventos');
insert into public.produtos(id,loja_id,bling_id,sku,nome,situacao) values ('ed100000-0000-0000-0000-000000000001','ed000000-0000-0000-0000-000000000001','123','NANO-EV1','Original','A');
insert into public.produto_automacao(produto_id,loja_id,pausado) values ('ed100000-0000-0000-0000-000000000001','ed000000-0000-0000-0000-000000000001',true);
insert into public.nano_lifecycle_checkpoint(loja_id,habilitado) values ('ed000000-0000-0000-0000-000000000001',true);
create temp table evento as select jsonb_build_array(jsonb_build_object('produto_id','ed100000-0000-0000-0000-000000000001','loja_id','ed000000-0000-0000-0000-000000000001','bling_id','123','sku','NANO-EV1','tipo','alteracao_tecnica','campos','["nome"]'::jsonb,'revisao','sync_0002','idempotency_key','nano-lifecycle:'||encode(sha256(convert_to('["ed000000-0000-0000-0000-000000000001","ed100000-0000-0000-0000-000000000001","123","sync_0002","alteracao_tecnica"]','UTF8')),'hex'),'destino','pesquisa','pausado_na_captura',true)) dados;
grant select on evento to service_role;
set local role service_role;
select pg_temp.afirma(public.nano_lifecycle_reservar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000001')->>'geracao'='1','reserva baseline');
select pg_temp.afirma(public.nano_lifecycle_registrar_varredura('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000001',1,'{"ativos":[["123"]],"inativos":[[]],"excluidos":[[]]}')->>'estado'='registrada','evidência baseline');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000001',1,'sync_0001',null,'baseline','[]','[]',repeat('a',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='gravado','baseline sem histórico');
select pg_temp.afirma(public.nano_lifecycle_reservar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002')->>'geracao'='2','segunda reserva');
select pg_temp.afirma(public.nano_lifecycle_gravar_espelho('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'[{"loja_id":"ed000000-0000-0000-0000-000000000001","bling_id":"123","sku":"NANO-EV1","nome":"Alterado","preco":null,"estoque":null,"situacao":"A","categoria_bling_id":null,"marca":null,"gtin":null,"gtin_tributario":null,"descricao_curta":null,"descricao_complementar":null,"peso_kg":null,"largura_cm":null,"altura_cm":null,"profundidade_cm":null,"unidade":null,"condicao":null,"formato":null,"pai_bling_id":null,"volumes":null,"sincronizado_em":"2026-11-26T12:00:00Z"}]'::jsonb)=1,'alteração técnica real');
select pg_temp.afirma(public.nano_lifecycle_registrar_varredura('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'{"ativos":[["123"]],"inativos":[[]],"excluidos":[[]]}')->>'estado'='registrada','evidência nova');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao','[]','[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','omissão de alteração bloqueada');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select dados||dados from evento),'[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','duplicidade bloqueada');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select jsonb_set(dados,'{0,campos}','["marca"]') from evento),'[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','campo inventado bloqueado');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select jsonb_set(dados,'{0,pausado_na_captura}','false') from evento),'[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','pausa divergente bloqueada');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select jsonb_set(dados,'{0,idempotency_key}',to_jsonb('nano-lifecycle:'||repeat('c',64))) from evento),'[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','chave inventada bloqueada');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select dados from evento),'[{"produto_id":"ed100000-0000-0000-0000-000000000001","motivo":"sku_duplicado"}]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='eventos_divergentes','bloqueio inventado recusado');
select pg_temp.afirma((select revisao='sync_0001' from public.nano_lifecycle_checkpoint where loja_id='ed000000-0000-0000-0000-000000000001'),'checkpoint intacto após recusas');
select pg_temp.afirma(public.nano_lifecycle_finalizar('ed000000-0000-0000-0000-000000000001','ed200000-0000-0000-0000-000000000002',2,'sync_0002','sync_0001','pronto_para_transacao',(select dados from evento),'[]',repeat('b',64),public.nano_lifecycle_projecao('ed000000-0000-0000-0000-000000000001'))='gravado','evento completo e pausa real aceitos');
select pg_temp.afirma((select eventos=(select dados from evento) from public.nano_lifecycle_capturas where loja_id='ed000000-0000-0000-0000-000000000001' and revisao='sync_0002'),'captura persistida corresponde à prova');
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='desabilitado','despacho desabilitado por padrão');
reset role;
update public.nano_lifecycle_checkpoint set despacho_habilitado=true where loja_id='ed000000-0000-0000-0000-000000000001';
set local role service_role;
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='pausado','pausa atual impede despacho');
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002','chave_inventada')->>'estado'='evento_inexistente','evento inventado recusado');
reset role;
update public.produto_automacao set pausado=false where produto_id='ed100000-0000-0000-0000-000000000001';
set local role service_role;
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='orcamento_indisponivel','sem orçamento não cria tarefa');
select pg_temp.afirma((select count(*)=0 from public.pipeline_itens where loja_id='ed000000-0000-0000-0000-000000000001'),'nenhuma tarefa criada sem autorização');
reset role;
insert into public.pipeline_orcamentos(loja_id,mes,limite_usd) values ('ed000000-0000-0000-0000-000000000001',date_trunc('month',now())::date,1);
set local role service_role;
select pg_temp.afirma(public.pipeline_criar('ed000000-0000-0000-0000-000000000001','NANO-EV1','ed100000-0000-0000-0000-000000000001','{}','legacy-teste') is not null,'simula item legado ativo');
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='pipeline_ativo_aguardar','não duplica item ativo');
update public.pipeline_itens set estado='rejeitado' where loja_id='ed000000-0000-0000-0000-000000000001' and idempotency_key='legacy-teste';
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='encaminhado','evento validado cria item na fila existente');
select pg_temp.afirma(public.nano_lifecycle_encaminhar('ed000000-0000-0000-0000-000000000001','sync_0002',(select dados->0->>'idempotency_key' from evento))->>'estado'='ja_encaminhado','repetição retorna item existente');
select pg_temp.afirma((select count(*)=1 from public.pipeline_itens where loja_id='ed000000-0000-0000-0000-000000000001' and entrada->>'origem'='nano_lifecycle' and estado='entrada' and produto_id='ed100000-0000-0000-0000-000000000001'),'um único item de entrada correto');
select pg_temp.afirma((select count(*)=0 from public.pipeline_custos where loja_id='ed000000-0000-0000-0000-000000000001'),'nenhum custo executado');
select pg_temp.afirma((select count(*)=1 from public.pipeline_historico h join public.pipeline_itens i on i.id=h.item_id where i.loja_id='ed000000-0000-0000-0000-000000000001' and i.entrada->>'origem'='nano_lifecycle'),'histórico inicial registrado');
reset role;
select pg_temp.afirma(not has_column_privilege('service_role','public.nano_lifecycle_checkpoint','despacho_habilitado','update') and not has_function_privilege('anon','public.nano_lifecycle_encaminhar(uuid,text,text)','execute'),'ativação administrativa e RPC privada');
rollback;
